210	static void clock_update_cb(lv_timer_t *timer)
211	{
212	    (void)timer;
213	    time_t now;
214	    struct tm tm;
215	    time(&now);
216	    /* Board has no TZ config: force UTC+8 (same as luncher_dm update_time_cb) */
217	    struct tm *utc = gmtime(&now);
218	    if (utc == NULL) return;
219	    tm = *utc;
220	    tm.tm_hour += 8;
221	    mktime(&tm);
222	
223	    char buf[32];
224	
225	    /* Time HH:MM */
226	    snprintf(buf, sizeof(buf), "%02d:%02d", tm.tm_hour, tm.tm_min);
227	    lv_label_set_text(clock_label, buf);
228	    if (clock_big_label)
229	        lv_label_set_text(clock_big_label, buf);
230	    if (standby_clock_label)
231	        lv_label_set_text(standby_clock_label, buf);
232	
233	    /* Date: Thu  Jul 24 */
234	    static const char *en_weekdays[] =
235	        { "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
236	    static const char *en_months[] =
237	        { "Jan", "Feb", "Mar", "Apr", "May", "Jun",
238	          "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
239	    snprintf(buf, sizeof(buf), "%s  %s %d",
240	             en_weekdays[tm.tm_wday],
241	             en_months[tm.tm_mon],
242	             tm.tm_mday);
243	    if (clock_date_label)
244	        lv_label_set_text(clock_date_label, buf);
245	    if (standby_date_label)
246	        lv_label_set_text(standby_date_label, buf);
247	}
