256	    const char *name = (const char *)lv_obj_get_user_data(btn);
257	    LV_LOG_USER("Launch app: %s", name ? name : "unknown");
258	    reset_idle_timer();
259	
260	    /* iOS-style tap dim: icon fades to 50% then back, then launch */
261	    lv_anim_t a;
262	    lv_anim_init(&a);
263	    lv_anim_set_var(&a, btn);
264	    lv_anim_set_exec_cb(&a, fade_dim_cb);
265	    lv_anim_set_values(&a, 255, 128);   /* 100% → 50% opacity */
266	    lv_anim_set_time(&a, 80);
267	    lv_anim_set_playback_time(&a, 120);
268	    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
269	    lv_anim_set_repeat_count(&a, 1);
270	    lv_anim_set_ready_cb(&a, launch_app_after_fade);
271	    lv_anim_set_user_data(&a, (void *)name);
272	    lv_anim_start(&a);
273	}
